const I3={};let I3R=null;
function icon3d(name){if(I3[name]!==undefined)return I3[name];I3[name]=null;try{
 if(!I3R){I3R=new THREE.WebGLRenderer({alpha:true,antialias:true,preserveDrawingBuffer:true});I3R.setSize(160,160,false);I3R.setClearColor(0,0);I3R.outputColorSpace=THREE.SRGBColorSpace}
 const sc=new THREE.Scene();sc.add(new THREE.HemisphereLight('#ffffff','#7a6a80',1.5));const dl=new THREE.DirectionalLight('#fff4e0',2.6);dl.position.set(-2,4,3);sc.add(dl);const rl=new THREE.DirectionalLight('#9ad8ff',1.1);rl.position.set(3,-1,-2);sc.add(rl);
 const grp=new THREE.Group();let fit=1.5;
 if(name==='wood'){const m=new THREE.Mesh(barkGeo(.5,.5,1.7,28),LOGMATS);m.rotation.set(0,0,Math.PI/2);grp.add(m);grp.rotation.set(.35,-.75,.1);fit=2.0}
 else if(name==='stone'){const m=new THREE.Mesh(pebbleGeo(1),lootMat.stone);grp.add(m);grp.rotation.set(.5,.4,0);fit=1.2}
 else{const mt=lootMat.ore.clone();mt.emissiveIntensity=.3;const add=(h,r,x,z,rx,rz)=>{const m=new THREE.Mesh(shardGeo(1),mt);m.scale.set(r*1.3,h*.62,r*1.3);m.position.set(x,-.9+h*.93,z);m.rotation.set(rx,0,rz);grp.add(m)};
  if(name==='ore'){add(1.0,.5,0,0,0,0)}else{add(1.0,.46,0,0,0,0);add(.7,.34,-.6,.15,0,.35);add(.62,.3,.55,.1,0,-.4)}
  grp.rotation.set(.2,.5,0);fit=1.7}
 sc.add(grp);new THREE.Box3().setFromObject(grp).getCenter(grp.position).multiplyScalar(-1);
 const bb=new THREE.Box3().setFromObject(grp),bs=bb.getSize(new THREE.Vector3()),sz=Math.max(bs.x,bs.y)*1.12;
 const cam=new THREE.OrthographicCamera(-sz/2,sz/2,sz/2,-sz/2,.1,50);cam.position.set(0,0,10);cam.lookAt(0,0,0);
 I3R.render(sc,cam);const c=document.createElement('canvas');c.width=c.height=160;c.getContext('2d').drawImage(I3R.domElement,0,0);I3[name]=c}catch(e){I3[name]=null}return I3[name]}
function icon(name,size=64){const c=document.createElement('canvas');c.width=c.height=size;const x=c.getContext('2d');
 if(name==='wood'||name==='stone'||name==='ore'||name==='crystal'){const im=icon3d(name);if(im){x.imageSmoothingQuality='high';x.drawImage(im,0,0,size,size);return c}}
 x.scale(size/64,size/64);(ICON[name]||ICON.bag)(x);return c}
function costChips(c,skipCoins){const d=document.createElement('div');d.className='chips';for(const k in c){if(skipCoins&&k==='coins')continue;const ok=haveOf(k)>=c[k];const e=document.createElement('span');e.className='chip'+(ok?'':' no');e.appendChild(icon(ICON[k]?k:'bag',32));const b=document.createElement('b');b.textContent=fmtC(c[k]);e.appendChild(b);d.appendChild(e)}return d}
const costSig=c=>Object.keys(c).map(k=>haveOf(k)>=c[k]?1:0).join('');
function putIcon(el,name){el.innerHTML='';el.appendChild(icon(name,72))}
const $=id=>document.getElementById(id);
const fmt=n=>{n=Math.floor(n);if(n>=1e6)return (n/1e6).toFixed(n>=1e7?0:1)+'M';if(n>=1e4)return (n/1e3).toFixed(n>=1e5?0:1)+'K';return n.toLocaleString()};
const fmtC=n=>Math.floor(n).toLocaleString();

